import React, { useState, useEffect } from 'react';
import axios from 'axios';
import moment from 'moment'; // We'll still use moment for easy date formatting

const AttendancePage = () => {
  const [allTimeLogs, setAllTimeLogs] = useState([]);
  const [isLoading, setIsLoading] = useState(true);

  // State for our filters
  const [filters, setFilters] = useState({
    department: 'All',
    // Default to the past 7 days
    startDate: moment().subtract(7, 'days').format('YYYY-MM-DD'),
    endDate: moment().format('YYYY-MM-DD'),
  });

  // Fetch data when the component loads
  useEffect(() => {
    // In a real app, you'd fetch this from '/api/timelogs/?start=...&end=...'
    // For now, we simulate the data.
    const mockTimeLogs = [
      { id: 1, employee: { id: 1, firstName: 'Dr. Anjali', lastName: 'Rao', department: 'Computer Science' }, date: '2025-10-26', clockIn: '09:05 AM', clockOut: '05:00 PM', status: 'Present' },
      { id: 2, employee: { id: 2, firstName: 'Prof. Vikram', lastName: 'Kumar', department: 'Mathematics' }, date: '2025-10-26', clockIn: '09:35 AM', clockOut: '05:10 PM', status: 'Discrepancy' },
      { id: 3, employee: { id: 3, firstName: 'Dr. Priya', lastName: 'Mehta', department: 'Physics' }, date: '2025-10-26', clockIn: '--:--', clockOut: '--:--', status: 'Absent' },
      { id: 4, employee: { id: 1, firstName: 'Dr. Anjali', lastName: 'Rao', department: 'Computer Science' }, date: '2025-10-25', clockIn: '09:00 AM', clockOut: '05:02 PM', status: 'Present' },
      { id: 5, employee: { id: 2, firstName: 'Prof. Vikram', lastName: 'Kumar', department: 'Mathematics' }, date: '2025-10-25', clockIn: '--:--', clockOut: '--:--', status: 'On Leave' },
    ];
    setAllTimeLogs(mockTimeLogs);
    setIsLoading(false);
  }, []);

  const handleFilterChange = (e) => {
    setFilters({ ...filters, [e.target.name]: e.target.value });
  };

  // Filter the data based on state before rendering
  const filteredLogs = allTimeLogs.filter(log => {
    const logDate = moment(log.date);
    const startDate = moment(filters.startDate);
    const endDate = moment(filters.endDate);
    const inDateRange = logDate.isBetween(startDate, endDate, 'day', '[]'); // '[]' includes start/end dates

    const inDepartment = filters.department === 'All' || log.employee.department === filters.department;

    return inDateRange && inDepartment;
  });

  const getStatusBadge = (status) => { /* ... (same as before) ... */ };

  return (
    <div className="p-8">
      <div className="flex justify-between items-center mb-6">
        <div>
          <h1 className="text-3xl font-bold text-text-light dark:text-text-dark">Attendance Log</h1>
          <p className="text-sm text-subtext-light">Filter and review attendance records based on time tracking data.</p>
        </div>
      </div>

      {/* Filter Bar */}
      <div className="p-4 bg-card-light dark:bg-card-dark rounded-lg shadow-sm mb-6">
        <div className="grid grid-cols-1 md:grid-cols-3 gap-4 items-end">
          <div>
            <label className="block text-sm font-medium text-subtext-light">Department</label>
            <select name="department" value={filters.department} onChange={handleFilterChange} className="mt-1 w-full">
              <option>All</option>
              <option>Computer Science</option>
              <option>Mathematics</option>
              <option>Physics</option>
              <option>Administration</option>
            </select>
          </div>
          <div>
            <label className="block text-sm font-medium text-subtext-light">Start Date</label>
            <input type="date" name="startDate" value={filters.startDate} onChange={handleFilterChange} className="mt-1 w-full" />
          </div>
          <div>
            <label className="block text-sm font-medium text-subtext-light">End Date</label>
            <input type="date" name="endDate" value={filters.endDate} onChange={handleFilterChange} className="mt-1 w-full" />
          </div>
        </div>
      </div>

      {/* Data Table */}
      <div className="bg-card-light dark:bg-card-dark rounded-xl shadow-sm overflow-x-auto">
        <table className="w-full text-sm text-left">
          <thead className="text-xs uppercase bg-background-light">
            <tr>
              <th className="px-6 py-3">Employee</th>
              <th className="px-6 py-3">Date</th>
              <th className="px-6 py-3">Clock In</th>
              <th className="px-6 py-3">Clock Out</th>
              <th className="px-6 py-3">Status</th>
            </tr>
          </thead>
          <tbody>
            {isLoading ? (
              <tr><td colSpan="5" className="text-center py-10 text-subtext-light">Loading...</td></tr>
            ) : filteredLogs.length === 0 ? (
              <tr><td colSpan="5" className="text-center py-10 text-subtext-light">No records found for the selected filters.</td></tr>
            ) : (
              filteredLogs.map(log => (
                <tr key={log.id} className="border-b hover:bg-gray-50">
                  <td className="px-6 py-4 font-medium text-text-light dark:text-white">
                    {log.employee.firstName} {log.employee.lastName}
                  </td>
                  <td className="px-6 py-4">{log.date}</td>
                  <td className="px-6 py-4">{log.clockIn}</td>
                  <td className="px-6 py-4">{log.clockOut}</td>
                  <td className="px-6 py-4">{getStatusBadge(log.status)}</td>
                </tr>
              ))
            )}
          </tbody>
        </table>
      </div>
    </div>
  );
};

// You can keep this helper function in the file
const getStatusBadge = (status) => {
    switch (status) {
      case 'Present': return <span className="inline-flex items-center px-2.5 py-0.5 rounded-full text-xs font-medium bg-green-100 text-green-800">Present</span>;
      case 'Discrepancy': return <span className="inline-flex items-center px-2.5 py-0.5 rounded-full text-xs font-medium bg-yellow-100 text-yellow-800">Discrepancy</span>;
      case 'Absent': return <span className="inline-flex items-center px-2.5 py-0.5 rounded-full text-xs font-medium bg-red-100 text-red-800">Absent</span>;
      case 'On Leave': return <span className="inline-flex items-center px-2.5 py-0.5 rounded-full text-xs font-medium bg-orange-100 text-orange-800">On Leave</span>;
      default: return null;
    }
};

export default AttendancePage;
